// 5/25 demo: 把过去 5 分钟的转写文本累加到 flow context
const WINDOW_MS = 5 * 60 * 1000;
const text = (msg.payload && msg.payload.text) || '';
if (!text) return null;
let buf = flow.get('transcript_window') || [];
buf.push({ ts: Date.now(), text });
const cutoff = Date.now() - WINDOW_MS;
buf = buf.filter(e => e.ts >= cutoff);
flow.set('transcript_window', buf);
return null;  // 单纯缓存，不下游

// 5/25 demo: 取 5min 窗口拼成 LLM 请求
const buf = flow.get('transcript_window') || [];
if (buf.length === 0) {
    return { payload: { text: '过去 5 分钟未捕获到转写内容', is_empty: true } };
}
const joined = buf.map(e => e.text).join(' ');
const prompt = `下面是过去 5 分钟的会议/对话转写，请用 3-5 个 bullet 简要总结要点，重点抓: 决策、待办、风险。\n\n转写内容:\n${joined}\n\n请输出 markdown bullet 列表，不超过 200 字。`;
return {
    topic: 'av/llm/command',
    payload: {
        prompt,
        mode: 'summary',
        source: 'node-red-demo-c',
        window_count: buf.length,
        ts: Date.now()
    }
};
